import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for GroupNorm+Tanh+HardSwish+Residual
fused_gn_act_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <algorithm>

__device__ __forceinline__ float hard_swish(float x) {
    return x * __fminf(__fmaxf(x + 3.0f, 0.0f), 6.0f) / 6.0f;
}

__global__ void fused_gn_act_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int C, int H, int W,
    int groups, float eps) {

    const int group_id = blockIdx.x;
    const int group_size = C / groups;
    const int N = B * group_size * H * W;

    extern __shared__ float smem[];
    float* sum = smem;
    float* sum_sq = smem + 1;

    if(threadIdx.x == 0) {
        *sum = 0.0f;
        *sum_sq = 0.0f;
    }
    __syncthreads();

    // Compute group statistics
    for(int idx = threadIdx.x; idx < N; idx += blockDim.x) {
        const int b = idx / (group_size * H * W);
        const int c = group_id * group_size + (idx / (H * W)) % group_size;
        const int hw = idx % (H * W);
        const float val = input[((b * C + c) * H + hw / W) * W + hw % W];

        atomicAdd(sum, val);
        atomicAdd(sum_sq, val * val);
    }
    __syncthreads();

    const float mean = *sum / N;
    const float var = (*sum_sq / N) - (mean * mean);
    const float inv_std = rsqrtf(var + eps);
    const float scale = weight[group_id];
    const float shift = bias[group_id];

    // Apply fused operations
    for(int idx = threadIdx.x; idx < N; idx += blockDim.x) {
        const int b = idx / (group_size * H * W);
        const int c = group_id * group_size + (idx / (H * W)) % group_size;
        const int hw = idx % (H * W);
        const int in_idx = ((b * C + c) * H + hw / W) * W + hw % W;

        const float x = input[in_idx];
        const float norm = (x - mean) * inv_std * scale + shift;
        const float activated = hard_swish(tanhf(norm));
        output[in_idx] = x + activated;
    }
}

torch::Tensor fused_gn_act_residual_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int groups, float eps) {

    auto output = torch::empty_like(input);
    const int B = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    dim3 grid(groups);
    dim3 block(256);
    size_t smem = 2 * sizeof(float);

    fused_gn_act_kernel<<<grid, block, smem>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, H, W,
        groups, eps
    );

    return output;
}
"""

fused_gn_act_cpp = """
torch::Tensor fused_gn_act_residual_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int groups, float eps);
"""

fused_gn_act = load_inline(
    name='fused_gn_act',
    cpp_sources=fused_gn_act_cpp,
    cuda_sources=fused_gn_act_source,
    functions=['fused_gn_act_residual_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, groups, eps=1e-5):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.groups = groups
        self.eps = eps

        # Initialize group norm parameters
        self.weight = nn.Parameter(torch.ones(out_channels))
        self.bias = nn.Parameter(torch.zeros(out_channels))

    def forward(self, x):
        x_conv = self.conv(x)
        x_res = fused_gn_act.fused_gn_act_residual_cuda(
            x_conv, self.weight, self.bias, self.groups, self.eps
        )
        return torch.logsumexp(x_res, dim=1, keepdim=True)
